                }
            }


            else
            {
                cmd.addArg(t);

                if (stopAtNonOption)
                {
                    eatTheRest = true;
                }
            }


            if (eatTheRest)
            {
                while (iterator.hasNext())
                {
                    final String str = iterator.next();


                    if (!"--".equals(str))
